import { ref, onMounted } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElButton, ElRate } from "element-plus"; // 引入 Element Plus 组件

export default {
  __name: 'ProductPage',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const route = useRoute(); // 获取当前路由
    const router = useRouter(); // 获取路由实例

    const product = ref({}); // 存储商品信息
    const rating = ref(0); // 存储评分

    // 获取商品详情
    onMounted(async () => {
      const productId = route.params.id; // 从路由获取商品 ID
      const response = await fetch(`/api/products/${productId}`); // 请求商品详情 API
      if (response.ok) {
        product.value = await response.json(); // 将商品信息存储
      } else {
        console.error("获取商品详情失败");
      }
    });

    // 加入购物车
    const addToCart = () => {
      alert(`${product.value.title} 已加入购物车！`); // 模拟加入购物车
    };

    // 跳转到购物车页面
    const goToCart = () => {
      router.push("/cart"); // 导航到购物车页面
    };
    const __returned__ = {
      route,
      router,
      product,
      rating,
      addToCart,
      goToCart,
      ref,
      onMounted,
      get useRoute() {
        return useRoute;
      },
      get useRouter() {
        return useRouter;
      },
      get ElButton() {
        return ElButton;
      },
      get ElRate() {
        return ElRate;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
